msg.query = `
SELECT
  (SELECT row_to_json(s) FROM (SELECT admin_name, school_name, academic_year, semester FROM app_settings WHERE id = 1) s) AS greeting,
  (SELECT json_build_object(
    'total_siswa', COUNT(*)::int,
    'siswa_perempuan', COUNT(*) FILTER (WHERE jenis_kelamin = 'Perempuan')::int,
    'siswa_laki_laki', COUNT(*) FILTER (WHERE jenis_kelamin = 'Laki-laki')::int,
    'total_kelas', COUNT(DISTINCT kelas)::int
  ) FROM students) AS stats,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT id, nis, nama, kelas, jenis_kelamin, status FROM students ORDER BY created_at ASC LIMIT 5) t) AS top_students,
  (SELECT COALESCE(json_agg(i), '[]'::json) FROM (SELECT id, nis, nama, kelas, jenis_kelamin, status FROM students WHERE status = 'Tidak Aktif' ORDER BY nama ASC) i) AS inactive_students;
`;
return msg;

const row = msg.payload[0] || {};
msg.statusCode = 200;
msg.payload = {
    success: true,
    data: {
        greeting: row.greeting || {},
        stats: row.stats || { total_siswa: 0, siswa_perempuan: 0, siswa_laki_laki: 0, total_kelas: 0 },
        top_students: row.top_students || [],
        inactive_students: row.inactive_students || []
    }
};
return msg;

const page = Math.max(1, parseInt(msg.req.query.page) || 1);
const rawLimit = parseInt(msg.req.query.limit) || 5;
const limit = [5, 10].includes(rawLimit) ? rawLimit : 5;
const offset = (page - 1) * limit;
const search = (msg.req.query.search || '').trim().replace(/'/g, "''");

msg.meta_req = { page, limit };

const whereClause = search 
  ? `WHERE nama ILIKE '%${search}%' OR nis ILIKE '%${search}%' OR kelas ILIKE '%${search}%' OR jenis_kelamin ILIKE '%${search}%'`
  : '';

msg.query = `
SELECT
  (SELECT COUNT(*)::int FROM students ${whereClause}) AS total_items,
  (SELECT COALESCE(json_agg(row_data), '[]'::json) FROM (
    SELECT id, nis, nama, kelas, jenis_kelamin, status
    FROM students
    ${whereClause}
    ORDER BY created_at DESC
    LIMIT ${limit} OFFSET ${offset}
  ) row_data) AS items;
`;
return msg;

const row = msg.payload[0] || { total_items: 0, items: [] };
const { page, limit } = msg.meta_req;
const total_pages = Math.max(1, Math.ceil(row.total_items / limit));

msg.statusCode = 200;
msg.payload = {
    success: true,
    data: row.items,
    meta: {
        page,
        limit,
        total_items: row.total_items,
        total_pages
    }
};
return msg;

const b = msg.payload || {};
const errors = {};

if (!b.nis || !String(b.nis).trim()) errors.nis = 'NIS wajib diisi';
if (!b.nama || !String(b.nama).trim()) errors.nama = 'Nama wajib diisi';
if (!b.kelas || !String(b.kelas).trim()) errors.kelas = 'Kelas wajib diisi';
if (!['Laki-laki', 'Perempuan'].includes(b.jenis_kelamin)) errors.jenis_kelamin = 'Jenis kelamin harus Laki-laki atau Perempuan';
if (!['Aktif', 'Tidak Aktif'].includes(b.status)) errors.status = 'Status harus Aktif atau Tidak Aktif';

if (Object.keys(errors).length > 0) {
    msg.statusCode = 400;
    msg.payload = { success: false, message: 'Validasi gagal', errors };
    return [null, msg];
}

const esc = (v) => String(v).trim().replace(/'/g, "''");
msg.query = `
INSERT INTO students (nis, nama, kelas, jenis_kelamin, status)
VALUES ('${esc(b.nis)}', '${esc(b.nama)}', '${esc(b.kelas)}', '${esc(b.jenis_kelamin)}', '${esc(b.status)}')
RETURNING id, nis, nama, kelas, jenis_kelamin, status;
`;
return [msg, null];

msg.statusCode = 201;
msg.payload = {
    success: true,
    message: 'Data siswa berhasil ditambahkan',
    data: msg.payload[0]
};
return msg;

const id = (msg.req.params.id || '').replace(/'/g, "''");
const b = msg.payload || {};
const errors = {};

if (!b.nis || !String(b.nis).trim()) errors.nis = 'NIS wajib diisi';
if (!b.nama || !String(b.nama).trim()) errors.nama = 'Nama wajib diisi';
if (!b.kelas || !String(b.kelas).trim()) errors.kelas = 'Kelas wajib diisi';
if (!['Laki-laki', 'Perempuan'].includes(b.jenis_kelamin)) errors.jenis_kelamin = 'Jenis kelamin harus Laki-laki atau Perempuan';
if (!['Aktif', 'Tidak Aktif'].includes(b.status)) errors.status = 'Status harus Aktif atau Tidak Aktif';

if (Object.keys(errors).length > 0) {
    msg.statusCode = 400;
    msg.payload = { success: false, message: 'Validasi gagal', errors };
    return [null, msg];
}

const esc = (v) => String(v).trim().replace(/'/g, "''");
msg.query = `
UPDATE students
SET nis = '${esc(b.nis)}', nama = '${esc(b.nama)}', kelas = '${esc(b.kelas)}', jenis_kelamin = '${esc(b.jenis_kelamin)}', status = '${esc(b.status)}', updated_at = NOW()
WHERE id = '${id}'
RETURNING id, nis, nama, kelas, jenis_kelamin, status;
`;
return [msg, null];

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = { success: false, message: 'Data siswa tidak ditemukan' };
    return msg;
}
msg.statusCode = 200;
msg.payload = {
    success: true,
    message: 'Data siswa berhasil diperbarui',
    data: msg.payload[0]
};
return msg;

const id = (msg.req.params.id || '').replace(/'/g, "''");
msg.query = `DELETE FROM students WHERE id = '${id}' RETURNING id;`;
return msg;

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = { success: false, message: 'Data siswa tidak ditemukan' };
    return msg;
}
msg.statusCode = 200;
msg.payload = { success: true, message: 'Data siswa berhasil dihapus' };
return msg;

msg.statusCode = 200;
msg.payload = {
    success: true,
    data: msg.payload[0] || {}
};
return msg;

const b = msg.payload || {};
const errors = {};
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!b.admin_name || !String(b.admin_name).trim()) errors.admin_name = 'Nama pengguna wajib diisi';
if (!b.admin_email || !emailRegex.test(String(b.admin_email).trim())) errors.admin_email = 'Format email tidak valid';
if (!b.school_name || !String(b.school_name).trim()) errors.school_name = 'Nama sekolah wajib diisi';
if (!b.academic_year || !String(b.academic_year).trim()) errors.academic_year = 'Tahun ajaran wajib diisi';
if (!['Ganjil', 'Genap'].includes(b.semester)) errors.semester = 'Semester harus Ganjil atau Genap';

if (Object.keys(errors).length > 0) {
    msg.statusCode = 400;
    msg.payload = { success: false, message: 'Validasi gagal', errors };
    return [null, msg];
}

const esc = (v) => String(v).trim().replace(/'/g, "''");
msg.query = `
UPDATE app_settings
SET admin_name = '${esc(b.admin_name)}', admin_email = '${esc(b.admin_email)}', school_name = '${esc(b.school_name)}', academic_year = '${esc(b.academic_year)}', semester = '${esc(b.semester)}', updated_at = NOW()
WHERE id = 1
RETURNING admin_name, admin_email, school_name, academic_year, semester;
`;
return [msg, null];

msg.statusCode = 200;
msg.payload = {
    success: true,
    message: 'Pengaturan berhasil disimpan',
    data: msg.payload[0]
};
return msg;

const errMsg = (msg.error && msg.error.message) ? msg.error.message : 'Internal Server Error';

if (errMsg.includes('unique constraint') || errMsg.includes('students_nis_key')) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: 'Validasi gagal',
        errors: { nis: 'NIS sudah terdaftar pada siswa lain' }
    };
} else if (errMsg.includes('invalid input syntax for type uuid')) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: 'Format ID siswa (UUID) tidak valid'
    };
} else {
    msg.statusCode = 500;
    msg.payload = {
        success: false,
        message: 'Terjadi kesalahan pada database',
        detail: errMsg
    };
}
return msg;
